// الناحية التي تقع فيها نقطة (ray casting) — null خارج بغداد
export function nahiyaAt(lat: number, lng: number): BaghdadAdminShape | null {
  for (const n of BAGHDAD_NAHIYAS) {
    for (const ring of n.rings) {
      let inside = false;
      for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const [yi, xi] = ring[i], [yj, xj] = ring[j];
        if ((yi > lat) !== (yj > lat) && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
      }
      if (inside) return n;
    }
  }
  return null;
}
